CREATE TABLE public.exercises (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name text NOT NULL,
  slug text UNIQUE,
  category text NOT NULL DEFAULT 'strength',
  muscle_groups text[] NOT NULL DEFAULT '{}',
  equipment text[] NOT NULL DEFAULT '{}',
  difficulty text NOT NULL DEFAULT 'beginner',
  setting text NOT NULL DEFAULT 'home',
  sports text[] NOT NULL DEFAULT '{}',
  default_sets integer,
  default_reps text,
  duration_sec integer,
  rest_sec integer,
  instructions text[] NOT NULL DEFAULT '{}',
  safety_cues text[] NOT NULL DEFAULT '{}',
  contraindications text[] NOT NULL DEFAULT '{}',
  alternatives text[] NOT NULL DEFAULT '{}',
  progressions text[] NOT NULL DEFAULT '{}',
  regressions text[] NOT NULL DEFAULT '{}',
  video_url text,
  min_age integer,
  data_source text NOT NULL DEFAULT 'Unverified',
  source_url text,
  confidence text NOT NULL DEFAULT 'medium',
  verified boolean NOT NULL DEFAULT false,
  created_by uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

GRANT SELECT ON public.exercises TO anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.exercises TO authenticated;
GRANT ALL ON public.exercises TO service_role;

ALTER TABLE public.exercises ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Anyone can read exercises" ON public.exercises FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY "Users can add exercises" ON public.exercises FOR INSERT TO authenticated WITH CHECK (auth.uid() = created_by);
CREATE POLICY "Users can edit own exercises" ON public.exercises FOR UPDATE TO authenticated USING (auth.uid() = created_by) WITH CHECK (auth.uid() = created_by);
CREATE POLICY "Users can delete own exercises" ON public.exercises FOR DELETE TO authenticated USING (auth.uid() = created_by);

CREATE TRIGGER update_exercises_updated_at BEFORE UPDATE ON public.exercises
FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();

CREATE INDEX exercises_category_idx ON public.exercises (category);
CREATE INDEX exercises_name_idx ON public.exercises (lower(name));

CREATE TABLE public.training_plans (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL,
  name text NOT NULL DEFAULT 'Training plan',
  goal text,
  focus text[] NOT NULL DEFAULT '{}',
  fitness_level text,
  age_range text,
  equipment text[] NOT NULL DEFAULT '{}',
  sport text,
  days_per_week integer NOT NULL DEFAULT 3,
  session_minutes integer NOT NULL DEFAULT 45,
  week jsonb NOT NULL DEFAULT '[]'::jsonb,
  rationale text,
  safety_notes text[] NOT NULL DEFAULT '{}',
  adjustments jsonb NOT NULL DEFAULT '[]'::jsonb,
  inputs_signature text,
  active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

GRANT SELECT, INSERT, UPDATE, DELETE ON public.training_plans TO authenticated;
GRANT ALL ON public.training_plans TO service_role;

ALTER TABLE public.training_plans ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Users manage own training plans" ON public.training_plans FOR ALL TO authenticated
USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id);

CREATE TRIGGER update_training_plans_updated_at BEFORE UPDATE ON public.training_plans
FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();

ALTER TABLE public.workouts
  ADD COLUMN IF NOT EXISTS perceived_effort integer,
  ADD COLUMN IF NOT EXISTS exercises jsonb NOT NULL DEFAULT '[]'::jsonb,
  ADD COLUMN IF NOT EXISTS rest_day boolean NOT NULL DEFAULT false,
  ADD COLUMN IF NOT EXISTS plan_id uuid;

INSERT INTO public.exercises (name, slug, category, muscle_groups, equipment, difficulty, setting, sports, default_sets, default_reps, duration_sec, rest_sec, instructions, safety_cues, contraindications, alternatives, progressions, regressions, min_age, data_source, source_url, confidence, verified) VALUES
('Bodyweight squat','bodyweight-squat','strength','{quadriceps,glutes,core}','{none}','beginner','home','{}',3,'10-15',NULL,60,'{"Stand with feet shoulder-width apart, toes slightly out.","Push hips back and bend knees, keeping chest tall.","Lower until thighs are near parallel or as far as comfortable.","Drive through mid-foot to stand, squeezing glutes at the top."}','{"Keep knees tracking over toes, not caving inward.","Stop at the depth where your lower back stays neutral.","Breathe in on the way down, out on the way up."}','{"Acute knee or hip injury","Recent lower-limb surgery without clearance"}','{"Box squat","Wall sit","Split squat"}','{"Tempo squat (3s down)","Jump squat","Goblet squat"}','{"Box squat to a chair","Partial-range squat"}',NULL,'ACSM movement guidelines','https://www.acsm.org','high',true),
('Push-up','push-up','strength','{chest,triceps,shoulders,core}','{none}','beginner','home','{}',3,'6-15',NULL,60,'{"Set hands slightly wider than shoulders, body in one line.","Brace your core and glutes.","Lower chest toward the floor with elbows about 45° from your body.","Press back to the start without letting hips sag."}','{"Do not flare elbows to 90°.","Keep neck neutral, eyes just ahead of your hands.","Reduce range before letting form break down."}','{"Acute shoulder, elbow or wrist pain"}','{"Incline push-up","Knee push-up","Dumbbell bench press"}','{"Feet-elevated push-up","Tempo push-up","Archer push-up"}','{"Wall push-up","Incline push-up on a bench"}',NULL,'ACSM movement guidelines','https://www.acsm.org','high',true),
('Incline push-up','incline-push-up','strength','{chest,triceps,shoulders}','{bench}','beginner','home','{}',3,'8-15',NULL,60,'{"Place hands on a stable bench, table or wall.","Walk feet back so your body forms a straight line.","Lower chest to the surface under control.","Press back up."}','{"The higher the surface, the easier the exercise.","Keep hips level with shoulders."}','{"Acute shoulder or wrist pain"}','{"Knee push-up","Wall push-up"}','{"Lower the surface","Standard push-up"}','{"Wall push-up"}',NULL,'ACSM movement guidelines','https://www.acsm.org','high',true),
('Glute bridge','glute-bridge','strength','{glutes,hamstrings,core}','{none}','beginner','home','{}',3,'12-20',NULL,45,'{"Lie on your back, knees bent, feet flat and hip-width apart.","Press through your heels and lift hips until shoulders, hips and knees line up.","Pause for one second and squeeze your glutes.","Lower with control."}','{"Do not over-arch the lower back at the top.","Ribs stay down, core braced."}','{"Acute lower-back pain that worsens with extension"}','{"Hip thrust","Single-leg glute bridge"}','{"Single-leg glute bridge","Barbell hip thrust"}','{"Shorter range of motion"}',NULL,'ACSM movement guidelines','https://www.acsm.org','high',true),
('Plank','plank','stability','{core,shoulders,glutes}','{none}','beginner','home','{}',3,NULL,30,45,'{"Set forearms under shoulders, feet hip-width apart.","Brace your core and squeeze glutes so your body is one straight line.","Breathe steadily and hold."}','{"Stop the set when hips start to sag or pike — quality over duration.","Do not hold your breath."}','{"Late pregnancy","Acute lower-back pain"}','{"Knee plank","Dead bug","Bird dog"}','{"Long-lever plank","Plank with shoulder taps"}','{"Knee plank","Incline plank on a bench"}',NULL,'ACSM core training guidance','https://www.acsm.org','high',true),
('Dead bug','dead-bug','stability','{core,hip flexors}','{none}','beginner','home','{}',3,'8-10 each side',NULL,45,'{"Lie on your back, arms straight up, hips and knees at 90°.","Press your lower back gently into the floor.","Slowly lower one arm and the opposite leg.","Return and switch sides."}','{"Only go as far as you can without the lower back lifting.","Move slowly — this is a control drill, not a speed drill."}','{}','{"Bird dog","Plank"}','{"Straight-leg dead bug","Add a light weight"}','{"Heels-only dead bug"}',NULL,'NSCA core stability guidance','https://www.nsca.com','high',true),
('Bird dog','bird-dog','stability','{core,glutes,back}','{none}','beginner','home','{}',3,'8-10 each side',NULL,45,'{"Start on hands and knees, spine neutral.","Extend one arm forward and the opposite leg back.","Hold 2 seconds without rotating the hips.","Return and switch."}','{"Keep hips square to the floor.","Do not arch the lower back to gain reach."}','{}','{"Dead bug","Plank"}','{"Add a pause or a resistance band"}','{"Leg-only or arm-only version"}',NULL,'NSCA core stability guidance','https://www.nsca.com','high',true),
('Walking lunge','walking-lunge','strength','{quadriceps,glutes,hamstrings}','{none}','intermediate','home','{}',3,'8-12 each leg',NULL,60,'{"Step forward into a lunge, both knees bending to about 90°.","Keep torso tall and core braced.","Drive through the front heel to bring the back leg through.","Continue alternating."}','{"Front knee stays over the middle of the foot.","Take a shorter step if balance is unsteady."}','{"Acute knee pain","Balance impairment without support"}','{"Split squat","Reverse lunge","Step-up"}','{"Add dumbbells","Deficit lunge"}','{"Static split squat holding a wall"}',NULL,'ACSM movement guidelines','https://www.acsm.org','high',true),
('Reverse lunge','reverse-lunge','strength','{quadriceps,glutes,hamstrings}','{none}','beginner','home','{}',3,'8-12 each leg',NULL,60,'{"Step one foot back and lower the back knee toward the floor.","Keep the front shin close to vertical.","Push through the front foot to return to standing."}','{"Stepping backwards is usually kinder to the knees than stepping forwards.","Hold a wall for balance if needed."}','{"Acute knee pain"}','{"Split squat","Step-up"}','{"Add dumbbells","Deficit reverse lunge"}','{"Supported split squat"}',NULL,'ACSM movement guidelines','https://www.acsm.org','high',true),
('Goblet squat','goblet-squat','strength','{quadriceps,glutes,core}','{dumbbell,kettlebell}','beginner','gym','{}',3,'8-12',NULL,90,'{"Hold a dumbbell or kettlebell at chest height.","Squat down between your hips, elbows inside the knees.","Keep the chest up and drive back to standing."}','{"Let the weight act as a counterbalance — chest stays tall.","Do not round the lower back at the bottom."}','{"Acute knee or back injury"}','{"Bodyweight squat","Leg press"}','{"Front squat","Barbell back squat"}','{"Bodyweight squat","Box squat"}',NULL,'NSCA resistance training guidance','https://www.nsca.com','high',true),
('Barbell back squat','barbell-back-squat','strength','{quadriceps,glutes,hamstrings,core}','{barbell,squat rack}','advanced','gym','{}',4,'5-8',NULL,150,'{"Set the bar on your upper back, hands just outside the shoulders.","Unrack, step back, feet shoulder-width.","Brace, sit down and back to depth you control.","Drive up through mid-foot."}','{"Always use safety pins or a spotter.","Stop the set when depth or bar path breaks down.","Build load gradually — no more than about 5-10% per week."}','{"Uncontrolled hypertension","Acute back or knee injury","Beginners without coaching"}','{"Goblet squat","Leg press","Hack squat"}','{"Increase load gradually","Pause squat"}','{"Goblet squat","Box squat"}',16,'NSCA resistance training guidance','https://www.nsca.com','high',true),
('Romanian deadlift','romanian-deadlift','strength','{hamstrings,glutes,back}','{barbell,dumbbell}','intermediate','gym','{}',3,'6-10',NULL,120,'{"Hold the bar at hip height, knees softly bent.","Push hips back and slide the bar down your thighs.","Stop when you feel a hamstring stretch with a flat back.","Drive hips forward to stand."}','{"The spine stays neutral throughout — no rounding.","Range is limited by your hamstrings, not by touching the floor."}','{"Acute lower-back injury","Disc symptoms without clearance"}','{"Hip hinge with a dowel","Cable pull-through","Glute bridge"}','{"Single-leg RDL","Increase load gradually"}','{"Dumbbell RDL with lighter load","Hip hinge drill"}',16,'NSCA resistance training guidance','https://www.nsca.com','high',true),
('Deadlift','deadlift','strength','{hamstrings,glutes,back,grip}','{barbell}','advanced','gym','{}',4,'3-6',NULL,180,'{"Stand mid-foot under the bar, grip just outside the knees.","Set your back flat, chest up, lats engaged.","Push the floor away and stand tall.","Return the bar under control along the same path."}','{"Never round the lower back under load.","Leave 1-2 reps in reserve on most sets.","Load progression should stay conservative and gradual."}','{"Acute back injury","Uncontrolled hypertension","Untrained lifters without coaching"}','{"Trap-bar deadlift","Romanian deadlift","Hip thrust"}','{"Add small increments","Deficit deadlift"}','{"Rack pull","Trap-bar deadlift"}',16,'NSCA resistance training guidance','https://www.nsca.com','high',true),
('Dumbbell bench press','dumbbell-bench-press','strength','{chest,triceps,shoulders}','{dumbbell,bench}','intermediate','gym','{}',3,'8-12',NULL,90,'{"Lie on a bench with a dumbbell in each hand at chest level.","Press up until the arms are straight, wrists over elbows.","Lower with control to a comfortable stretch."}','{"Keep shoulder blades pulled back and down.","Do not bounce the weights off your chest."}','{"Acute shoulder impingement"}','{"Push-up","Machine chest press"}','{"Increase load","Single-arm press"}','{"Incline push-up","Machine press"}',NULL,'NSCA resistance training guidance','https://www.nsca.com','high',true),
('Bent-over row','bent-over-row','strength','{back,biceps,rear delts}','{barbell,dumbbell}','intermediate','gym','{}',3,'8-12',NULL,90,'{"Hinge forward to about 45°, back flat.","Pull the weight to your lower ribs, elbows close.","Lower under control."}','{"Do not jerk with the lower back.","Keep the neck in line with the spine."}','{"Acute lower-back pain"}','{"Seated cable row","Single-arm dumbbell row","Inverted row"}','{"Increase load","Pendlay row"}','{"Chest-supported row"}',NULL,'NSCA resistance training guidance','https://www.nsca.com','high',true),
('Inverted row','inverted-row','strength','{back,biceps,core}','{barbell,squat rack}','beginner','gym','{}',3,'6-12',NULL,75,'{"Set a bar at hip height and lie underneath it.","Grip just wider than shoulders, body in a straight line.","Pull your chest to the bar, squeezing shoulder blades.","Lower with control."}','{"Higher bar = easier. Adjust before form breaks.","Keep hips up — no sagging."}','{}','{"Seated row","Band row"}','{"Feet-elevated row","Weighted vest"}','{"Raise the bar height","Bent-knee row"}',NULL,'NSCA resistance training guidance','https://www.nsca.com','high',true),
('Pull-up','pull-up','strength','{back,biceps,core}','{pull-up bar}','advanced','gym','{}',4,'3-8',NULL,120,'{"Hang from the bar with hands just wider than shoulders.","Pull your chest toward the bar, driving elbows down.","Lower all the way under control."}','{"Avoid swinging or kipping unless coached.","Use a band or assisted machine to build up."}','{"Acute shoulder or elbow injury"}','{"Band-assisted pull-up","Lat pulldown","Inverted row"}','{"Weighted pull-up"}','{"Negative pull-up","Lat pulldown"}',NULL,'NSCA resistance training guidance','https://www.nsca.com','high',true),
