('Farmer carry','farmer-carry','strength','{grip,core,traps}','{dumbbell,kettlebell}','beginner','gym','{}',3,NULL,40,60,'{"Pick up a heavy weight in each hand with a flat back.","Stand tall, shoulders down, core braced.","Walk with controlled steps for the set distance or time."}','{"Do not let the shoulders shrug or the torso lean.","Set the weights down with a hinge, not a round back."}','{"Acute back injury"}','{"Suitcase carry","Front rack carry"}','{"Heavier load","Longer distance"}','{"Lighter load","Shorter distance"}',NULL,'NSCA resistance training guidance','https://www.nsca.com','high',true),
('Brisk walking','brisk-walking','endurance','{cardiovascular,legs}','{none}','beginner','home','{}',NULL,NULL,1800,0,'{"Walk at a pace where you can talk but not sing.","Keep posture tall, arms swinging naturally.","Build duration before speed."}','{"Wear supportive shoes.","Start with 10-15 minutes if you are new to exercise."}','{}','{"Stationary cycling","Elliptical"}','{"Add incline","Increase pace or duration by ~10% per week"}','{"Shorter walks split through the day"}',NULL,'WHO physical activity guidelines','https://www.who.int/publications/i/item/9789240015128','high',true),
